// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("/", async (string? status, string? search, IShipmentService service) =>
    await service.GetShipmentsAsync(status, search));

shipments.MapGet("/{id:int}", async (int id, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByIdAsync(id);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
{
    await service.UpdateStatusAsync(id, newStatus);
    return Results.NoContent();
});

app.Run();

